const $ = id => document.getElementById(id);
let lesson=0,phase='learn',index=0;
const canvas=$('game'),ctx=canvas.getContext('2d');
let player={x:3,y:0},trafficTime=0,lastTime=0,hopTime=0;
const traffic=[{row:1,speed:.65,offset:.5,color:'#e8b95b'},{row:2,speed:-.85,offset:4,color:'#d77c5e'},{row:4,speed:.75,offset:2,color:'#8fadae'}];
function iso(x,y,z=0){return {x:500+(x-3)*69+(y-2.5)*56,y:359+(x-3)*30-(y-2.5)*34-z};}
function poly(points,color){ctx.fillStyle=color;ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fill();}
function tile(x,y,color){poly([iso(x-.5,y-.5),iso(x+.5,y-.5),iso(x+.5,y+.5),iso(x-.5,y+.5)],color);}
function box(x,y,w,d,h,top,left,right){const a=iso(x-w/2,y-d/2),b=iso(x+w/2,y-d/2),c=iso(x+w/2,y+d/2),e=iso(x-w/2,y+d/2);const lift=p=>({x:p.x,y:p.y-h});poly([a,b,lift(b),lift(a)],left);poly([b,c,lift(c),lift(b)],right);poly([lift(a),lift(b),lift(c),lift(e)],top);}
function tree(x,y,size=1){box(x,y,.16,.16,24*size,'#80674d','#80674d','#6b583f');box(x,y,.55*size,.55*size,59*size,'#77a250','#5f8c3d','#527b35');box(x,y,.4*size,.4*size,73*size,'#8bb75c','#739a47','#638f3e');}
function car(x,y,c){box(x,y,1.13,.65,20,c,c,'#a3654d');box(x-.12,y,.53,.55,36,c,'#d7e7d7','#688482');const p=iso(x+.35,y-.36,10),q=iso(x-.37,y-.36,10);ctx.fillStyle='#354339';ctx.fillRect(p.x-7,p.y,12,13);ctx.fillRect(q.x-7,q.y,12,13);}
function bird(){const bounce=performance.now()-hopTime<170?12*Math.sin((performance.now()-hopTime)/170*Math.PI):0;const p=iso(player.x,player.y);ctx.fillStyle='#30492f33';ctx.beginPath();ctx.ellipse(p.x,p.y+6,24,11,0,0,Math.PI*2);ctx.fill();box(player.x,player.y,.45,.44,30+bounce,'#fff6df','#e7dec8','#d9ceb6');box(player.x,player.y+.13,.34,.29,49+bounce,'#fff9e9','#f0e7d1','#e3d8bd');box(player.x+.23,player.y+.15,.19,.14,35+bounce,'#f4b349','#d39232','#cf8a2d');const eye=iso(player.x+.19,player.y+.24,43+bounce);ctx.fillStyle='#253e32';ctx.fillRect(eye.x-2,eye.y-2,4,5);box(player.x-.05,player.y+.12,.11,.15,56+bounce,'#e37b54','#c76847','#bf6246');}
function draw(time){const dt=Math.min((time-lastTime)/1000,.05)||0;lastTime=time;if(typeof roadRunFrame==='function'&&roadRunFrame(time,dt)){requestAnimationFrame(draw);return;}trafficTime+=dt;ctx.clearRect(0,0,1000,720);ctx.fillStyle='#b6cf94';ctx.fillRect(0,0,1000,720);for(let y=8;y>=-3;y--)for(let x=-5;x<12;x++)tile(x,y,((x+y)%3===0)?'#b0cb8b':'#b6cf94');for(let y=6;y>=0;y--)for(let x=-3;x<10;x++){let road=[1,2,4].includes(y);tile(x,y,road?'#727f70':y===5?'#c9d8a0':(x+y)%2?'#9cbd75':'#a3c57c');if(road&&x%2===0)box(x,y,.4,.045,.3,'#b8bda2','#b8bda2','#b8bda2');}for(const p of [[-2,6],[-1,7],[1,8],[5,7],[8,6],[-2,3],[9,0],[-2,-1],[0,-2],[7,-2],[8,3]])tree(p[0],p[1],.8+(p[0]%3)*.12);for(let x=0;x<7;x++){box(x,6,.3,.04,12,'#f0e8b3','#e6d99e','#c7c488');}const objects=traffic.map(t=>({kind:'car',x:((trafficTime*t.speed+t.offset)%11+11)%11-2,y:t.row,t}));objects.push({kind:'bird',x:player.x,y:player.y});objects.sort((a,b)=>iso(a.x,a.y).y-iso(b.x,b.y).y);objects.forEach(o=>o.kind==='bird'?bird():car(o.x,o.y,o.t.color));if(typeof checkCollision==='function')checkCollision(objects);requestAnimationFrame(draw);}
requestAnimationFrame(draw);

const STORAGE='wort-hop-progress-v1';
let saved={xp:0,completed:[],memory:{},sound:true};
try{const raw=JSON.parse(localStorage.getItem(STORAGE)||'null');if(raw&&Number.isFinite(raw.xp)&&Array.isArray(raw.completed)&&raw.memory&&typeof raw.memory==='object'){saved={...saved,...raw,completed:raw.completed.filter(n=>Number.isInteger(n)&&n>=0&&n<COURSE.length)};}}catch{}
let reviewMode=false,queue=[],attempts=0,sessionCorrect=0,bumps=0,checkpoint=false,checkpointScore=0,checkpointRound=0,selectedTokens=[],currentOptions=[],listening=false,invincibleUntil=0,lastMove=0;
const esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normalize=s=>s.toLocaleLowerCase('de').trim().replace(/[.!?,]/g,'').replace(/ä/g,'ae').replace(/ö/g,'oe').replace(/ü/g,'ue').replace(/ß/g,'ss').replace(/\s+/g,' ');
const shuffle=a=>{const b=[...a];for(let j=b.length-1;j>0;j--){const k=Math.floor(Math.random()*(j+1));[b[j],b[k]]=[b[k],b[j]];}return b;};
function memoryKey(w){return w[0];}
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(saved));$('save-status').textContent='Progress saved on this device';}catch{$('save-status').textContent='Storage unavailable — progress lasts this session';}renderStats();}
function knownWords(){return COURSE.flatMap(u=>u.words).filter(w=>saved.memory[memoryKey(w)]);}
function dueWords(){return knownWords().filter(w=>(saved.memory[memoryKey(w)].due||0)<=Date.now());}
function renderStats(){$('xp').textContent=saved.xp;$('due-count').textContent=dueWords().length;$('sound').textContent=saved.sound?'♪':'♩';$('sound').setAttribute('aria-label',saved.sound?'Turn pronunciation off':'Turn pronunciation on');$('sound').title=saved.sound?'Pronunciation on':'Pronunciation off';}
function renderCourses(){$('course-grid').innerHTML=COURSE.map((u,i)=>{const unlocked=i===0||saved.completed.includes(i-1),done=saved.completed.includes(i);return `<button class="course ${i===lesson&&!reviewMode?'active':''} ${!unlocked?'locked':''}" data-lesson="${i}" ${unlocked?'':'aria-disabled="true"'}><span class="unit-icon">${done?'✓':u.icon}</span><div><span class="unit-label">${done?'COMPLETED':unlocked?'READY TO HOP':'UP NEXT'}</span><strong>${u.title}</strong></div><span class="lock">${unlocked?'↗':'⌑'}</span></button>`;}).join('');document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>startLesson(Number(b.dataset.lesson)));}
function speak(text){if(!saved.sound){toast('Pronunciation is off. Use ♪ to turn it on.');return;}if(!('speechSynthesis' in window)){toast('Pronunciation isn’t supported by this browser. Read the German aloud.');return;}speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.lang='de-DE';utterance.rate=.82;const voice=speechSynthesis.getVoices().find(v=>v.lang.startsWith('de'));if(voice)utterance.voice=voice;utterance.onerror=()=>toast('Audio unavailable here — you can still read and play.');speechSynthesis.speak(utterance);}
function toast(text){$('game-toast').textContent=text;}
function word(){return queue[index];}
function startLesson(n){if(!Number.isInteger(n)||n<0||n>=COURSE.length)throw Error('Choose a valid lesson.');if(n>0&&!saved.completed.includes(n-1)){showDialog(`<span class="pill">ONE HOP AT A TIME</span><h2>Almost there.</h2><p>Finish “${esc(COURSE[n-1].title)}” to unlock this lesson. Each step builds on what you’ve already learned.</p>`);return false;}lesson=n;reviewMode=false;queue=COURSE[n].words;index=0;attempts=0;checkpoint=false;checkpointScore=0;checkpointRound=0;sessionCorrect=0;bumps=0;phase='learn';player={x:3,y:0};render();return true;}
function render(){renderStats();renderCourses();const u=COURSE[lesson];$('world-label').textContent=reviewMode?'THE MEMORY TRAIL':u.world.toUpperCase();$('lesson-label').textContent=reviewMode?'PRACTICE · WORD REVIEW':`LESSON ${u.icon} · ${u.title.toUpperCase()}`;$('lesson-number').textContent=`${Math.min(index+1,queue.length)} / ${queue.length}`;$('progress-fill').style.width=`${index/queue.length*100}%`;$('cross-count').textContent=checkpoint?'RECALL CHECKPOINT':`CROSSING ${String(Math.min(index+1,queue.length)).padStart(2,'0')} / ${String(queue.length).padStart(2,'0')}`;document.querySelector('.world-badge').innerHTML=`<span>${reviewMode?'↻':u.icon}</span><div>${reviewMode?'WIEDERHOLUNG':'WILLKOMMEN'}<br><b>${esc(reviewMode?'The memory meadow':u.world)}</b></div>`;if(phase==='learn')renderLearn();else if(phase==='question')renderQuestion();else if(phase==='cross')renderCross();}
function renderLearn(){const w=word();toast('Meet a word. Then make your move.');$('game-status').textContent='A little learning before the leap.';$('lesson-content').innerHTML=`<span class="pill">${index===0?'MEET YOUR FIRST WORD':'A NEW LITTLE DISCOVERY'}</span><h2>${lesson===0&&index===0?'Every adventure<br>starts with Hallo.':'A word for your journey.'}</h2><p>${index===0?esc(COURSE[lesson].tip):'Listen to the word and see it in a sentence.'}</p><div class="word-intro"><div class="word-row"><div><div class="german" style="${w[0].length>22?'font-size:24px':''}">${esc(w[0])}</div><div class="english">${esc(w[1])}</div></div><button id="listen" class="icon-button" aria-label="Listen to pronunciation">♪</button></div><div class="context">${esc(w[2])}<br><small>${esc(w[3])}</small></div></div><button id="learn-next" class="primary">I’m ready. Let’s try it. <span>→</span></button>`;$('listen').onclick=()=>speak(w[0]);$('learn-next').onclick=()=>{phase='question';attempts=0;render();};}
function questionType(){if(checkpoint)return lesson>=3?'recall':'choice';if(reviewMode)return'recall';if(lesson===7)return'sentence';if(lesson>=3&&index%2===0)return'recall';if(lesson>=1&&index===2&&saved.sound&&'speechSynthesis'in window)return'listen';return'choice';}
function renderQuestion(){const w=word(),type=questionType();listening=type==='listen';selectedTokens=[];toast(checkpoint?'Recall it without the word card.':'Find the word to open the crossing.');$('game-status').textContent=checkpoint?'A quick check before the next lesson.':'Answer first. Adventure next.';const title=checkpoint?'Let’s see what stuck.':type==='sentence'?'Build it in German.':type==='recall'?'Your turn, from memory.':type==='listen'?'Listen closely.':'Which word gets you across?';$('lesson-content').innerHTML=`<span class="pill">${checkpoint?'RECALL CHECKPOINT':reviewMode?'SPACED PRACTICE':type==='listen'?'LISTEN & RECOGNIZE':type==='recall'?'REMEMBER & TYPE':type==='sentence'?'PUT IT TOGETHER':'PICK YOUR PATH'}</span><h2>${title}</h2><p>${type==='listen'?'Listen to the German, then choose its English meaning.':type==='sentence'?'Arrange the words to translate:':'How do you say this in German?'}</p>${type==='listen'?'<button class="outline" id="listen">♪ Play German audio</button><button id="audio-fallback" class="quiet">Use a text question instead</button>':`<div class="english-prompt" style="font:600 23px 'Space Grotesk';margin:18px 0">“${esc(w[1])}”</div>`}<div id="question-controls"></div><div id="feedback" class="feedback" aria-live="polite"></div>`;
 const controls=$('question-controls');
 if(type==='choice'||type==='listen'){const side=type==='listen'?1:0;let pool=COURSE[lesson].words;if(reviewMode)pool=knownWords();currentOptions=shuffle([w[side],...shuffle([...new Set(pool.filter(v=>v[side]!==w[side]).map(v=>v[side]))]).slice(0,2)]);controls.innerHTML=`<div class="answers">${currentOptions.map((t,i)=>`<button class="answer" data-answer="${i}"><kbd>${i+1}</kbd>${esc(t)}</button>`).join('')}</div>`;document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answer(currentOptions[Number(b.dataset.answer)]));if(type==='listen'){$('listen').onclick=()=>speak(w[0]);$('audio-fallback').onclick=()=>{listening=false;saved.sound=false;save();renderQuestion();};}}
 else if(type==='recall'){controls.innerHTML='<form id="recall-form"><label class="sr-only" for="recall">German translation</label><input id="recall" class="recall" placeholder="Type the German…" autocomplete="off" spellcheck="false" autocapitalize="off"><button class="primary" type="submit">Check my answer <span>→</span></button></form><p style="font-size:11px;margin-top:9px">ä = ae · ö = oe · ü = ue · ß = ss</p>';$('recall-form').onsubmit=e=>{e.preventDefault();answer($('recall').value);};}
 else{const tokens=shuffle(w[0].split(' '));controls.innerHTML='<div class="sentence-output" id="sentence-output" aria-live="polite">Tap the words below…</div><div class="sentence-tokens">'+tokens.map((t,i)=>`<button data-token="${i}">${esc(t)}</button>`).join('')+'</div><button id="sentence-check" class="primary">Check sentence <span>→</span></button><button id="clear-sentence" class="quiet">Start sentence again</button>';document.querySelectorAll('[data-token]').forEach(b=>b.onclick=()=>{selectedTokens.push(tokens[Number(b.dataset.token)]);b.disabled=true;$('sentence-output').textContent=selectedTokens.join(' ');});$('clear-sentence').onclick=()=>{selectedTokens=[];$('sentence-output').textContent='Tap the words below…';document.querySelectorAll('[data-token]').forEach(b=>b.disabled=false);};$('sentence-check').onclick=()=>answer(selectedTokens.join(' '));}
}
function updateMemory(w,correct){const key=memoryKey(w),old=saved.memory[key]||{streak:0,due:0,seen:0};const today=new Date().toDateString();const streak=correct?Math.min((old.streak||0)+(old.lastSuccessDay===today?0:1),6):0;const intervals=[0,1,3,7,14,30,60];saved.memory[key]={streak,due:Date.now()+(correct?intervals[streak]*86400000:60000),seen:(old.seen||0)+1,lastSuccessDay:correct?today:null};save();}
function answer(value){if(phase!=='question')return {accepted:false,reason:'There is no active question.'};if(!String(value).trim()){$('feedback').textContent='Give it a try first.';return {accepted:false,reason:'An answer is required.'};}const w=word(),expected=w[listening?1:0],correct=normalize(String(value))===normalize(expected);attempts++;
if(!correct){updateMemory(w,false);$('feedback').className='feedback error';$('feedback').textContent=`Almost. ${w[0]} means “${w[1]}”. Take a look, then try again.`;document.querySelectorAll('[data-answer]').forEach(b=>{if(currentOptions[Number(b.dataset.answer)]===value)b.classList.add('wrong');});return{accepted:true,correct:false};}
if(attempts===1){sessionCorrect++;if(checkpoint)checkpointScore++;}updateMemory(w,attempts===1);saved.xp+=attempts===1?10:5;save();
if(checkpoint){phase='feedback';$('feedback').className='feedback';$('feedback').innerHTML=`Richtig! ${esc(w[0])}<button class="primary" id="checkpoint-next" style="margin-top:12px">${index===queue.length-1?'Finish checkpoint':'Next word'} <span>→</span></button>`;$('question-controls').querySelectorAll('button,input').forEach(b=>b.disabled=true);$('checkpoint-next').onclick=()=>{index++;attempts=0;if(index>=queue.length){if(checkpointScore>=Math.ceil(queue.length*.8)){completeLesson();}else{checkpointRound++;showDialog(`<span class="pill">KEEP GROWING</span><h2>${checkpointScore} of ${queue.length} from memory.</h2><p>Let’s aim for ${Math.ceil(queue.length*.8)} correct first tries before the next lesson. You can revisit the word cards or try the checkpoint again.</p><button class="primary" id="retry-checkpoint">Try checkpoint again →</button><button class="quiet" id="relearn">Revisit this lesson</button>`);$('retry-checkpoint').onclick=()=>{$('dialog').close();beginCheckpoint();};$('relearn').onclick=()=>{$('dialog').close();startLesson(lesson);};}}else{phase='question';render();}};}else{phase='cross';player={x:3,y:0};invincibleUntil=0;renderCross();if(saved.sound)speak(w[0]);}return{accepted:true,correct:true};}
function renderCross(){const w=word();toast('Richtig! Use ↑ to hop. Watch the traffic.');$('game-status').textContent='Arrow keys or tap the buttons to move.';$('lesson-content').innerHTML=`<span class="pill">RICHTIG! · ${attempts===1?'+10':'+5'} XP</span><h2>You’ve got the word.<br>Now make the hop.</h2><div class="word-intro"><div class="word-row"><div><div class="german" style="${w[0].length>22?'font-size:23px':''}">${esc(w[0])}</div><button class="icon-button" id="listen" aria-label="Listen to pronunciation">♪</button></div><div class="english">${esc(w[1])}</div><div class="context">${esc(w[2])}<br><small>${esc(w[3])}</small></div></div><p>Reach the far meadow. Pause on grass, dodge the cars, and keep hopping.</p><button id="gentle-hop" class="quiet">Skip the traffic · learning-only mode</button>`;$('listen').onclick=()=>speak(w[0]);$('gentle-hop').onclick=()=>finishCrossing();}
function move(direction){if(phase!=='cross'||$('dialog').open)return false;const now=performance.now();if(now-lastMove<115)return false;lastMove=now;const delta={left:[-1,0],right:[1,0],up:[0,1],down:[0,-1]}[direction];if(!delta)return false;player.x=Math.max(0,Math.min(6,player.x+delta[0]));player.y=Math.max(0,Math.min(6,player.y+delta[1]));hopTime=now;const cars=traffic.map(t=>({kind:'car',x:((trafficTime*t.speed+t.offset)%11+11)%11-2,y:t.row}));checkCollision(cars);if(player.y===6)finishCrossing();return true;}
function checkCollision(objects){if(phase!=='cross'||$('dialog').open||performance.now()<invincibleUntil)return;for(const o of objects)if(o.kind==='car'&&o.y===player.y&&Math.abs(o.x-player.x)<.68){player={x:3,y:0};bumps++;invincibleUntil=performance.now()+900;toast('Bump! Your word is safe. Try the crossing again.');break;}}
function finishCrossing(){if(phase!=='cross')return;phase='feedback';player.y=6;saved.xp+=5;save();toast('A small hop. A little more German.');$('game-status').textContent='Crossing complete · +5 XP';$('lesson-content').innerHTML=`<span class="pill">CROSSING COMPLETE · +5 XP</span><div class="big-icon">✦</div><h2>One word further.</h2><p>${esc(word()[0])} — ${esc(word()[1])}</p><button id="next-crossing" class="primary">${index===queue.length-1?(reviewMode?'Finish review':'Take the recall checkpoint'):'On to the next word'} <span>→</span></button>`;$('next-crossing').onclick=()=>{index++;attempts=0;player={x:3,y:0};if(index>=queue.length){reviewMode?completeReview():beginCheckpoint();}else{phase=reviewMode?'question':'learn';render();}};}
function beginCheckpoint(){checkpoint=true;checkpointScore=0;queue=shuffle(COURSE[lesson].words);index=0;attempts=0;phase='question';player={x:3,y:0};render();}
function completeLesson(){phase='complete';const newly=!saved.completed.includes(lesson);if(newly){saved.completed.push(lesson);saved.xp+=30;}save();renderCourses();$('progress-fill').style.width='100%';toast('Wunderbar! Your next adventure is ready.');$('lesson-content').innerHTML=`<span class="pill">LESSON COMPLETE${newly?' · +30 XP':''}</span><div class="big-icon">✺</div><h2>${lesson===7?'Look how far you’ve hopped.':'Hallo, progress.'}</h2><p>You recalled ${checkpointScore} of ${queue.length} on the first try. ${lesson===7?'You’ve finished all 8 starter lessons. Keep practicing with word review.':'Your next lesson is unlocked.'}</p><button id="continue-course" class="primary">${lesson===7?'Practice your words':'Start '+esc(COURSE[lesson+1].title)} <span>→</span></button><button class="quiet" id="lesson-again">Practice this lesson again</button>`;$('continue-course').onclick=()=>lesson===7?openReview():startLesson(lesson+1);$('lesson-again').onclick=()=>startLesson(lesson);}
function completeReview(){phase='complete';$('progress-fill').style.width='100%';$('lesson-content').innerHTML=`<span class="pill">MEMORY REFRESHED</span><div class="big-icon">↻</div><h2>A little stronger.</h2><p>You reviewed ${queue.length} words. Missed words return sooner; confident answers get a longer interval.</p><button id="back-course" class="primary">Back to your journey <span>→</span></button>`;$('back-course').onclick=()=>startLesson(Math.min(saved.completed.length,7));toast('Nice work. Come back for another little hop.');}
function openReview(){const known=knownWords(),due=dueWords();showDialog(`<span class="pill">YOUR GROWING VOCABULARY</span><h2>${known.length?`${known.length} words on your trail.`:'Your first word is waiting.'}</h2><p>${known.length?`${due.length} due for review. Missed words return after a minute; successful first tries are spaced 1, 3, 7, 14, 30, then 60 days apart.`:'Play your first lesson to start collecting words for review.'}</p>${known.length?`<div class="word-list">${known.map(w=>`<div><b>${esc(w[0])}</b><span>${esc(w[1])}</span></div>`).join('')}</div><button class="primary" id="start-review" style="margin-top:20px">${due.length?'Review due words':'Practice known words'} <span>→</span></button>`:''}`);if(known.length)$('start-review').onclick=()=>{queue=shuffle(due.length?due:known).slice(0,6);index=0;attempts=0;reviewMode=true;checkpoint=false;sessionCorrect=0;phase='question';player={x:3,y:0};$('dialog').close();render();};}
function showDialog(html){$('dialog-content').innerHTML=html;if(!$('dialog').open)$('dialog').showModal();}
$('close-dialog').onclick=()=>$('dialog').close();$('dialog').addEventListener('click',e=>{if(e.target===$('dialog')){const r=$('dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('dialog').close();}});
$('how').onclick=()=>showDialog('<span class="pill">WELCOME TO WORT HOP</span><h2>A little learning.<br>A little adventure.</h2><ol><li><b>Meet a word.</b> Read a short example and tap ♪ to hear German pronunciation.</li><li><b>Remember it.</b> Choose, type, or build the answer. Mistakes get a helpful correction.</li><li><b>Make your crossing.</b> Use arrow keys or the onscreen arrows to dodge cars and reach the far meadow. Up moves diagonally toward the far side of the isometric board.</li><li><b>Unlock your next step.</b> Recall at least 5 of 6 answers on the first try in the checkpoint.</li></ol><p>There is no answer timer. Bumps never erase learning. You can skip traffic whenever you want.</p>');
$('method').onclick=()=>showDialog('<span class="pill">HOW THE LEARNING WORKS</span><h2>Small steps, revisited.</h2><p>This original starter course moves from greetings and common nouns to present-tense statements, directions, and sentence building. It introduces beginner German; it is not a complete A1 qualification or a copy of either app’s curriculum.</p><p><b>Introduce → recognize → recall → review.</b> A checkpoint unlocks each next lesson. Your answers schedule local reviews; missed words come back sooner.</p><p>Inspired by <a href="https://blog.duolingo.com/how-are-duolingo-courses-evolving/" target="_blank" rel="noopener">Duolingo’s structured, contextual learning</a> and <a href="https://lingvist.com/help/why-do-i-see-the-same-words/" target="_blank" rel="noopener">Lingvist’s spaced repetition</a>. Our simple review schedule is independent of their proprietary algorithms.</p><p>Pronunciation uses available German voices on your device. Progress is saved only in this browser, with no account or cross-device sync.</p>');
$('review').onclick=openReview;$('sound').onclick=()=>{saved.sound=!saved.sound;if(!saved.sound&&'speechSynthesis'in window)speechSynthesis.cancel();save();};
document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>move(b.dataset.move));
document.addEventListener('keydown',e=>{if($('dialog').open||['INPUT','TEXTAREA'].includes(e.target.tagName))return;const dirs={ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right'};if(dirs[e.key]&&phase==='cross'){e.preventDefault();move(dirs[e.key]);}else if(phase==='question'&&['1','2','3'].includes(e.key)&&currentOptions.length&&document.querySelector('[data-answer]')){answer(currentOptions[Number(e.key)-1]);}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&phase==='cross'){player={x:3,y:0};toast('Welcome back. Start safely from the meadow.');}});
setInterval(renderStats,30000);
startLesson(Math.min(saved.completed.length,7));
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=t=>{try{Promise.resolve(document.modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}};register({name:'get_learning_progress',description:'Read device-local German course progress and the current lesson.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({xp:saved.xp,completedLessons:saved.completed.map(i=>COURSE[i].title),dueWords:dueWords().length,currentLesson:COURSE[lesson].title,phase})});register({name:'start_german_lesson',description:'Open an unlocked German lesson, restarting its current session. Lesson numbers are 1 through 8.',inputSchema:{type:'object',properties:{lessonNumber:{type:'integer',minimum:1,maximum:8}},required:['lessonNumber'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!Number.isInteger(input.lessonNumber)||input.lessonNumber<1||input.lessonNumber>8)throw Error('lessonNumber must be an integer from 1 to 8.');const n=input.lessonNumber-1;if(n>0&&!saved.completed.includes(n-1))throw Error('Finish the preceding lesson first.');startLesson(n);return{lesson:COURSE[n].title,phase};}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
